                if made_change:
                    break
                for c in range(target_color):
                    # BFS for Kempe chain (target_color, c)
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        x = stack.pop()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (color[y] == target_color or color[y] == c):
                                visited[y] = True
                                stack.append(y)
                    # check if any neighbor of component has color c (would cause conflict if swapped)
                    has_c_neighbor = False
                    for x in component:
                        for y in neighbors[x]:
                            if not visited[y] and color[y] == c:
                                has_c_neighbor = True
                                break
                        if has_c_neighbor:
                            break
                    if not has_c_neighbor:
                        for x in component:
                            if color[x] == target_color:
                                color[x] = c
                            elif color[x] == c:
                                color[x] = target_color
                        made_change = True
                        break
                if made_change:
                    break
            if not made_change:
                break
        return color

    # Helper: Smallest-Last peeling with iterative improvement
    def smallest_last_peeling():
        deg = degree[:]
        order = []
        deleted = [False] * n
        # Use bucket sort for efficiency
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            deleted[v] = True
            for u in neighbors[v]:
                if not deleted[u]:
                    d = deg[u]
                    if d > 0:
                        buckets[d].remove(u)
                        buckets[d-1].append(u)
                        deg[u] = d - 1
        order.reverse()
        # Now color in reverse peeling order with DSATUR-like saturation
        color = [-1] * n
        saturation = [set() for _ in range(n)]
        colored = [False] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if colored[u]:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
            colored[v] = True
            for u in neighbors[v]:
                if not colored[u]:
                    saturation[u].add(c)
        return color

    # Helper: Adaptive DSATUR with dynamic tie-breaking weights
    def adaptive_dsatur():
        color = [-1] * n
        colored = [False] * n
        saturation = [set() for _ in range(n)]
        # Dynamic weights: combine saturation, degree, and random perturbation
        for _ in range(n):
            # Select uncolored vertex with max saturation, then degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if not colored[i]:
                    sat = len(saturation[i])
                    deg = degree[i]
                    # Primary: saturation, secondary: degree, tertiary: random
                    if sat > max_sat or (sat == max_sat and deg > max_deg) or \
                       (sat == max_sat and deg == max_deg and random.random() < 0.5):
                        max_sat = sat
                        max_deg = deg
                        v = i
            if v == -1:
                break
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
            colored[v] = True
            for u in neighbors[v]:
                if not colored[u]:
                    saturation[u].add(c)
        return color

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(degeneracy_order())
    candidates.append(welsh_powell())
    candidates.append(smallest_last_peeling())
    candidates.append(adaptive_dsatur())

    # Random restarts of DSATUR with varied tie-breaking
    for _ in range(20):
        order = list(range(n))
        random.shuffle(order)
        color = [-1] * n
        colored = [False] * n
        saturation = [set() for _ in range(n)]
        for v in order:
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
            colored[v] = True
            for u in neighbors[v]:
                if not colored[u]:
                    saturation[u].add(c)
        candidates.append(color)

    # Evaluate candidates
    best_color = None
    best_k = float('inf')
    for col in candidates:
        if is_valid(col):
            k = max(col) + 1 if n > 0 else 0
            if k < best_k:
                best_k = k
                best_color = col
    # Fallback: greedy by degree
    if best_color is None:
        order = sorted(range(n), key=lambda x: (-degree[x], x))
        color = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        best_color = color
    # Apply Kempe reduction to improve
    best_color = kempe_reduce(best_color)
    # Final validation (should be valid)
    if not is_valid(best_color):
        order = sorted(range(n), key=lambda x: (-degree[x], x))
        color = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        best_color = color
    return best_color
